olitical Science','राजनीति विज्ञान'),(65,12,'Sociology','समाजशास्त्र'),(66,13,'Physics','भौतिक विज्ञान'),(67,13,'Chemistry','रसायन विज्ञान'),(68,13,'Biology','जीव विज्ञान'),(69,13,'Mathematics','गणित'),(70,13,'Accountancy','लेखाशास्त्र'),(71,13,'Business Studies','व्यवसाय अध्ययन'),(72,13,'Economics','अर्थशास्त्र'),(73,13,'History','इतिहास'),(74,13,'Political Science','राजनीति विज्ञान'),(75,13,'Sociology','समाजशास्त्र');
